import icontract
from typing import List


@icontract.ensure(lambda a, result: len(result) == len(a))
@icontract.ensure(lambda a, result: len(result) == len(a) and all(result[i] == a[len(a) - 1 - i] for i in range(len(a))))
def reverse(a: List[int]) -> List[int]:
    result = []
    i = len(a) - 1
    while i >= 0:
        result.append(a[i])
        i -= 1
    return result
